// ============================================
// Restaurant Feedback AI Analyzer
// Data Preparation Node
// ============================================

// Get data from Google Form
const customerName = $json["Customer Name"] ?? $json["Customer_Name"];
const email = $json["Email"];
const rate = Number($json["Rate"]);
const feedback = $json["FeedBack"] ?? $json["Feedback"];

// Validate required fields
if (!customerName) {
  throw new Error("Customer Name is required.");
}

if (!email) {
  throw new Error("Email is required.");
}

if (!Number.isInteger(rate) || rate < 1 || rate > 5) {
  throw new Error("Rate must be an integer between 1 and 5.");
}


// Clean feedback
const cleanFeedback = feedback.trim();
 typeof feedback === "string" ? feedback.trim() : "";

// Count words
const wordCount = cleanFeedback
  ? cleanFeedback.split(/\s+/).length
  : 0;

// Prepare data for AI analysis
const analysisInput = {
  customer_name: customerName,
  email: email,
  rate: rate,
  feedback: cleanFeedback,
  word_count: wordCount
};

// Return clean structured data
return [
  {
    json: {
      Customer_Name: customerName,
      Email: email,
      Rate: rate,
      FeedBack: cleanFeedback,
      Word_Count: wordCount,

      Analysis_Input: JSON.stringify(analysisInput)
    }
  }
];
